window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["スラング・若者言葉"]={
"_note": "スラング・若者言葉 — mỗi mục một dòng. LEVEL: s1 → s5 = 5 nhóm của chuyên đề (giữ nguyên nhãn gốc). THỨ TỰ: các nhóm xếp s1, s2, s3, s4, s5, không trộn lẫn; trong mỗi nhóm giữ nguyên thứ tự gốc. ĐỊNH DẠNG MỖI TỪ: word, reading, meaning, hanviet, example, example_reading, example_meaning, level, pos. TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: s1 26, s2 26, s3 25, s4 26, s5 26; tổng 129 mục từ vựng + 12 mẫu ngữ pháp (pattern, usage, example, example_reading, example_meaning).",
"id": "スラング・若者言葉",
"title": "スラング・若者言葉",
"icon": "💬",
"category": "main",
"kind": "slang",
"vocab": [
{"word":"それな","reading":"それな","meaning":"đúng thế! Chuẩn!","hanviet":"","example":"①「今日暑すぎ」「それな」\n②「このアニメ、神回だったね」「それな！」\n③「来週のテスト、だるすぎる」「それな〜」","example_reading":"①「きょうあつすぎ」「それな」\n②「このあにめ、かみかいだったね」「それな！」\n③「らいしゅうのてすと、だるすぎる」「それな〜」","example_meaning":"①\"Hôm nay nóng quá\" — \"Chuẩn!\"\n②\"Anime này tập hay quá nhỉ\" — \"Chuẩn luôn!\"\n③\"Bài kiểm tra tuần sau chán quá\" — \"Chuẩn rồi!\"","level":"s1","pos":"int"},
{"word":"わかりみ","reading":"わかりみ","meaning":"hiểu quá, thấm quá","hanviet":"","example":"①その気持ち、わかりみが深い。\n②月曜の朝に起きたくない気持ち、わかりみしかない。\n③「推しがいないと生きていけない」「わかりみ！」","example_reading":"①そのきもち、わかりみがふかい。\n②げつようのあさにおきたくないきもち、わかりみしかない。\n③「おしがいないといきていけない」「わかりみ！」","example_meaning":"①Cảm giác đó tôi hiểu sâu sắc luôn.\n②Cảm giác không muốn dậy sáng thứ Hai, tôi hiểu quá luôn.\n③\"Không có idol thì không sống nổi\" — \"Thấm quá đi!\"","level":"s1","pos":"n"},
{"word":"しんどい","reading":"しんどい","meaning":"mệt, đuối (cả nghĩa tốt lẫn xấu)","hanviet":"","antonym":"楽（らく）: nhàn, dễ chịu","antonym_hanviet":"lạc","example":"①推しが尊すぎてしんどい。\n②毎日残業でしんどい。\n③最終回が泣けてしんどかった。","example_reading":"①おしがとうとすぎてしんどい。\n②まいにちざんぎょうでしんどい。\n③さいしゅうかいがなけてしんどかった。","example_meaning":"①Idol của tôi đẹp quá làm tôi đuối luôn.\n②Ngày nào cũng tăng ca nên mệt rã rời.\n③Tập cuối cảm động quá làm tôi đuối luôn.","level":"s1","pos":"adj-i"},
{"word":"ガチ","reading":"ガチ","meaning":"thật sự, nghiêm túc","hanviet":"","antonym":"ネタ: đùa, không nghiêm túc","example":"①それガチで面白いよ。\n②ガチで焦った。\n③彼はガチ勢だから強いよ。","example_reading":"①それがちでおもしろいよ。\n②がちであせった。\n③かれはがちぜいだからつよいよ。","example_meaning":"①Cái đó thật sự hài luôn đấy.\n②Tôi hoảng thật sự luôn.\n③Cậu ấy là dân chơi nghiêm túc nên mạnh lắm.","level":"s1","pos":"adj-na"},
{"word":"マジ","reading":"マジ","meaning":"thật hả, thật sự","hanviet":"","antonym":"冗談（じょうだん）: đùa","antonym_hanviet":"nhũng đàm","example":"①マジで？信じられない。\n②マジで眠い。\n③「明日テストだよ」「マジ？」","example_reading":"①まじで？しんじられない。\n②まじでねむい。\n③「あしたてすとだよ」「まじ？」","example_meaning":"①Thật hả? Không tin nổi.\n②Buồn ngủ thật sự luôn.\n③\"Mai có bài kiểm tra đó\" — \"Thật hả?\"","level":"s1","pos":"adj-na"},
{"word":"やばい","reading":"やばい","meaning":"kinh khủng / đỉnh quá","hanviet":"","example":"①このケーキやばい、おいしい。\n②宿題やばい、全然終わらない。\n③このラーメン、やばいくらいうまい。","example_reading":"①このけーきやばい、おいしい。\n②しゅくだいやばい、ぜんぜんおわらない。\n③このらーめん、やばいくらいうまい。","example_meaning":"①Bánh này đỉnh thật, ngon quá.\n②Bài tập nguy rồi, mãi chưa xong.\n③Ramen này ngon đến mức \"điên\" luôn.","level":"s1","pos":"adj-i"},
{"word":"エモい","reading":"エモい","meaning":"đầy cảm xúc, bồi hồi","hanviet":"","example":"①夕焼けがエモい。\n②この曲、昔を思い出してエモい。\n③雨の日の電車ってエモいよね。","example_reading":"①ゆうやけがえもい。\n②このきょく、むかしをおもいだしてえもい。\n③あめのひのでんしゃってえもいよね。","example_meaning":"①Hoàng hôn gợi cảm xúc ghê.\n②Bài này làm tôi nhớ chuyện xưa, bồi hồi ghê.\n③Đi tàu ngày mưa có cảm giác bồi hồi nhỉ.","level":"s1","pos":"adj-i"},
{"word":"尊い","reading":"とうとい","meaning":"quá đẹp, quá đáng quý (về idol)","hanviet":"tôn","example":"①二人の関係が尊い。\n②推しの笑顔が尊い。\n③犬と赤ちゃんが並んで寝てるの、尊すぎる。","example_reading":"①ふたりのかんけいがとうとい。\n②おしのえがおがとうとい。\n③いぬとあかちゃんがならんでねてるの、とうとすぎる。","example_meaning":"①Mối quan hệ của hai người họ đáng quý quá.\n②Nụ cười của idol tôi quý giá quá.\n③Chó và em bé nằm ngủ cạnh nhau, đáng yêu quá trời.","level":"s1","pos":"adj-i"},
{"word":"推し","reading":"おし","meaning":"idol/nhân vật mình cày","hanviet":"suy","antonym":"アンチ: người anti","example":"①私の推しは彼女です。\n②推しのライブに行ってきた。\n③最近、新しい推しができた。","example_reading":"①わたしのおしはかのじょです。\n②おしのらいぶにいってきた。\n③さいきん、あたらしいおしができた。","example_meaning":"①Idol tôi hâm mộ là cô ấy.\n②Tôi vừa đi xem concert của idol mình về.\n③Dạo này tôi có idol mới.","level":"s1","pos":"n"},
{"word":"推し活","reading":"おしかつ","meaning":"hoạt động ủng hộ idol","hanviet":"suy hoạt","example":"①週末は推し活で忙しい。\n②推し活のためにバイトを増やした。\n③推し活でグッズを買いすぎた。","example_reading":"①しゅうまつはおしかつでいそがしい。\n②おしかつのためにばいとをふやした。\n③おしかつでぐっずをかいすぎた。","example_meaning":"①Cuối tuần tôi bận đi ủng hộ idol.\n②Tôi tăng ca làm thêm để lo cho việc ủng hộ idol.\n③Ủng hộ idol mà tôi lỡ mua quá nhiều đồ lưu niệm.","level":"s1","pos":"n"},
{"word":"沼","reading":"ぬま","meaning":"đầm lầy (nghiện không thoát ra được)","hanviet":"chiểu","example":"①このゲーム、完全に沼だ。\n②韓国ドラマの沼にはまった。\n③一度はまったら抜け出せない沼だよ。","example_reading":"①このげーむ、かんぜんにぬまだ。\n②かんこくどらまのぬまにはまった。\n③いちどはまったらぬけだせないぬまだよ。","example_meaning":"①Game này đúng là hố sâu không lối thoát.\n②Tôi sa vào \"hố sâu\" phim Hàn rồi.\n③Đó là cái hố đã sa vào thì không thoát ra được đâu.","level":"s1","pos":"n"},
{"word":"バズる","reading":"バズる","meaning":"viral, nổi rần rần","hanviet":"","example":"①その動画がバズった。\n②猫の動画がSNSでバズってる。\n③私の投稿が急にバズった。","example_reading":"①そのどうががばずった。\n②ねこのどうががえすえぬえすでばずってる。\n③わたしのとうこうがきゅうにばずった。","example_meaning":"①Video đó viral rồi.\n②Video con mèo đang viral trên mạng xã hội.\n③Bài đăng của tôi đột nhiên viral.","level":"s1","pos":"v"},
{"word":"映える","reading":"ばえる","meaning":"lên hình đẹp","hanviet":"ánh","example":"①この店、めっちゃ映える。\n②この夕日、写真に撮ると映えるよ。\n③赤い壁の前に立つと映える。","example_reading":"①このみせ、めっちゃばえる。\n②このゆうひ、しゃしんにとるとばえるよ。\n③あかいかべのまえにたつとばえる。","example_meaning":"①Quán này lên hình đẹp cực.\n②Hoàng hôn này chụp ảnh lên đẹp lắm.\n③Đứng trước bức tường đỏ lên hình rất đẹp.","level":"s1","pos":"v"},
{"word":"インスタ映え","reading":"インスタばえ","meaning":"đẹp để đăng Instagram","hanviet":"ánh","example":"①インスタ映えするカフェを探す。\n②インスタ映えを狙って、パンケーキを頼んだ。\n③この壁画はインスタ映えスポットとして有名だ。","example_reading":"①いんすたばえするかふぇをさがす。\n②いんすたばえをねらって、ぱんけーきをたのんだ。\n③このへきがはいんすたばえすぽっととしてゆうめいだ。","example_meaning":"①Tìm quán cà phê chụp lên Instagram đẹp.\n②Nhắm tới ảnh Instagram đẹp nên tôi gọi bánh pancake.\n③Bức tranh tường này nổi tiếng là điểm chụp lên Instagram rất đẹp.","level":"s1","pos":"n"},
{"word":"陰キャ","reading":"いんキャ","meaning":"người hướng nội, ít nói","hanviet":"âm","antonym":"陽キャ（ようキャ）: người hướng ngoại","antonym_hanviet":"dương","example":"①昔は陰キャだった。\n②私はどちらかというと陰キャだと思う。\n③陰キャでも友達はできるよ。","example_reading":"①むかしはいんきゃだった。\n②わたしはどちらかというといんきゃだとおもう。\n③いんきゃでもともだちはできるよ。","example_meaning":"①Hồi trước tôi khá hướng nội.\n②Tôi nghĩ mình thuộc kiểu hướng nội hơn.\n③Hướng nội cũng có bạn mà.","level":"s1","pos":"n"},
{"word":"陽キャ","reading":"ようキャ","meaning":"người hướng ngoại, sôi nổi","hanviet":"dương","antonym":"陰キャ（いんキャ）: người hướng nội","antonym_hanviet":"âm","example":"①彼は完全に陽キャだ。\n②陽キャの友達に誘われてパーティーに行った。\n③クラスの陽キャたちはいつも元気だ。","example_reading":"①かれはかんぜんによんきゃだ。\n②ようきゃのともだちにさそわれてぱーてぃーにいった。\n③くらすのようきゃたちはいつもげんきだ。","example_meaning":"①Cậu ấy đúng kiểu người sôi nổi.\n②Tôi được người bạn hướng ngoại rủ đi tiệc.\n③Mấy bạn sôi nổi trong lớp lúc nào cũng tràn năng lượng.","level":"s1","pos":"n"},
{"word":"リア充","reading":"リアじゅう","meaning":"người có đời thực viên mãn","hanviet":"sung","antonym":"ぼっち: một mình","example":"①リア充が羨ましい。\n②リア充の友達は毎週末予定がある。\n③彼氏もできて、完全にリア充だね。","example_reading":"①りあじゅうがうらやましい。\n②りあじゅうのともだちはまいしゅうまつよていがある。\n③かれしもできて、かんぜんにりあじゅうだね。","example_meaning":"①Ghen tị với mấy người đời thực viên mãn.\n②Bạn tôi sống đời thực viên mãn, cuối tuần nào cũng có kế hoạch.\n③Có cả bạn trai rồi, đúng là đời thực viên mãn nhỉ.","level":"s1","pos":"n"},
{"word":"ぼっち","reading":"ぼっち","meaning":"một mình, lẻ loi","hanviet":"","antonym":"リア充（リアじゅう）: người có đời thực viên mãn","antonym_hanviet":"sung","example":"①今日は昼ごはんぼっちだ。\n②休み時間はいつもぼっちだった。\n③ぼっち飯は意外と気楽だよ。","example_reading":"①きょうはひるごはんぼっちだ。\n②やすみじかんはいつもぼっちだった。\n③ぼっちめしはいがいときらくだよ。","example_meaning":"①Hôm nay tôi ăn trưa một mình.\n②Giờ ra chơi lúc nào tôi cũng lủi thủi một mình.\n③Ăn cơm một mình hóa ra khá thoải mái đấy.","level":"s1","pos":"n"},
{"word":"塩対応","reading":"しおたいおう","meaning":"đối xử lạnh nhạt","hanviet":"diêm đối ứng","antonym":"神対応（かみたいおう）: đối xử tuyệt vời","antonym_hanviet":"thần đối ứng","example":"①店員さんが塩対応だった。\n②推しに塩対応されて、逆に好きになった。\n③受付の人が塩対応でちょっと悲しい。","example_reading":"①てんいんさんがしおたいおうだった。\n②おしにしおたいおうされて、ぎゃくにすきになった。\n③うけつけのひとがしおたいおうでちょっとかなしい。","example_meaning":"①Nhân viên đối xử lạnh nhạt.\n②Bị idol đối xử lạnh nhạt mà tôi lại càng thích.\n③Người ở quầy tiếp tân lạnh nhạt nên tôi hơi buồn.","level":"s1","pos":"n"},
{"word":"神対応","reading":"かみたいおう","meaning":"đối xử cực tử tế","hanviet":"thần đối ứng","antonym":"塩対応（しおたいおう）: đối xử lạnh nhạt","antonym_hanviet":"diêm đối ứng","example":"①あの店は神対応だった。\n②問い合わせにすぐ返信が来て、神対応だった。\n③ファンへの神対応で人気が出た。","example_reading":"①あのみせはかみたいおうだった。\n②といあわせにすぐへんしんがきて、かみたいおうだった。\n③ふぁんへのかみたいおうでにんきがでた。","example_meaning":"①Quán đó phục vụ quá tử tế.\n②Hỏi xong được trả lời ngay, phục vụ quá tử tế.\n③Nhờ cách đối xử cực tử tế với fan mà anh ấy nổi tiếng.","level":"s1","pos":"n"},
{"word":"神","reading":"かみ","meaning":"đỉnh cao, thần thánh","hanviet":"thần","example":"①この機能、神すぎる。\n②昨日のライブ、神だった。\n③この店のカレーは神レベルだ。","example_reading":"①このきのう、かみすぎる。\n②きのうのらいぶ、かみだった。\n③このみせのかれーはかみれべるだ。","example_meaning":"①Tính năng này thần thánh thật.\n②Buổi diễn hôm qua đỉnh cao luôn.\n③Cà ri của quán này đạt mức thần thánh.","level":"s1","pos":"n"},
{"word":"草","reading":"くさ","meaning":"cười (giống \"haha\")","hanviet":"thảo","example":"①その話、草。\n②「寝坊した」「草」\n③その写真、草生える。","example_reading":"①そのはなし、くさ。\n②「ねぼうした」「くさ」\n③そのしゃしん、くさはえる。","example_meaning":"①Chuyện đó buồn cười ghê.\n②\"Tôi ngủ quên\" — \"Haha\"\n③Bức ảnh đó buồn cười quá trời.","level":"s1","pos":"n"},
{"word":"大草原","reading":"だいそうげん","meaning":"cười lăn lộn","hanviet":"đại thảo nguyên","example":"①彼の返信が大草原。\n②その動画、見てたら大草原だった。\n③コメント欄が大草原で笑った。","example_reading":"①かれのへんしんがだいそうげん。\n②そのどうが、みてたらだいそうげんだった。\n③こめんとらんがだいそうげんでわらった。","example_meaning":"①Tin nhắn của cậu ấy làm tôi cười lăn.\n②Xem video đó mà tôi cười lăn lộn luôn.\n③Phần bình luận toàn \"www\" làm tôi cười ngặt nghẽo.","level":"s1","pos":"n"},
{"word":"わろた","reading":"わろた","meaning":"cười mất (kiểu mạng)","hanviet":"","example":"①それ見てわろた。\n②友達の変顔にわろた。\n③さっきのギャグ、普通にわろた。","example_reading":"①それみてわろた。\n②ともだちのへんがおにわろた。\n③さっきのぎゃぐ、ふつうにわろた。","example_meaning":"①Xem cái đó tôi cười mất.\n②Tôi cười mất vì gương mặt hề của bạn.\n③Câu đùa lúc nãy làm tôi cười thật sự.","level":"s1","pos":"v"},
{"word":"うける","reading":"うける","meaning":"hài quá","hanviet":"","example":"①その話めっちゃうける。\n②彼のモノマネ、めっちゃうけた。\n③「本当にそう言ったの？」「うけるでしょ？」","example_reading":"①そのはなしめっちゃうける。\n②かれのものまね、めっちゃうけた。\n③「ほんとうにそういったの？」「うけるでしょ？」","example_meaning":"①Chuyện đó hài dã man.\n②Màn bắt chước của cậu ấy hài dã man.\n③\"Cậu ấy thật sự nói vậy à?\" — \"Hài đúng không?\"","level":"s1","pos":"v"},
{"word":"バグる","reading":"バグる","meaning":"lỗi, trục trặc (cả về người)","hanviet":"","example":"①頭がバグってる。\n②スマホがバグって動かない。\n③寝不足で脳がバグってる。","example_reading":"①あたまがばぐってる。\n②すまほがばぐってうごかない。\n③ねぶそくでのうがばぐってる。","example_meaning":"①Đầu tôi đang trục trặc rồi.\n②Điện thoại bị lỗi nên không chạy được.\n③Thiếu ngủ nên đầu óc rối loạn hết.","level":"s1","pos":"v"},
{"word":"めっちゃ","reading":"めっちゃ","meaning":"cực kỳ, rất (Kansai lan rộng)","hanviet":"","antonym":"ちょっと: một chút","example":"①今日めっちゃ寒い。\n②めっちゃ楽しかった！\n③このゲーム、めっちゃ難しい。","example_reading":"①きょうめっちゃさむい。\n②めっちゃたのしかった！\n③このげーむ、めっちゃむずかしい。","example_meaning":"①Hôm nay lạnh cực.\n②Vui cực kỳ luôn!\n③Game này khó cực kỳ.","level":"s2","pos":"adv"},
{"word":"超","reading":"ちょう","meaning":"siêu, cực","hanviet":"siêu","example":"①この店、超うまい。\n②今日は超いい天気だね。\n③超急いでるから、あとでね。","example_reading":"①このみせ、ちょううまい。\n②きょうはちょういいてんきだね。\n③ちょういそいでるから、あとでね。","example_meaning":"①Quán này siêu ngon.\n②Hôm nay thời tiết siêu đẹp nhỉ.\n③Tôi đang siêu vội nên để lát nhé.","level":"s2","pos":"pref"},
{"word":"鬼","reading":"おに","meaning":"cực kỳ (nhấn mạnh)","hanviet":"quỷ","example":"①鬼忙しい一日だった。\n②今日の坂道、鬼きつい。\n③昨日は疲れて、鬼寝た。","example_reading":"①おにいそがしいいちにちだった。\n②きょうのさかみち、おにきつい。\n③きのうはつかれて、おにねた。","example_meaning":"①Một ngày bận kinh khủng.\n②Con dốc hôm nay dốc kinh khủng.\n③Hôm qua mệt quá nên tôi ngủ cực nhiều.","level":"s2","pos":"pref"},
{"word":"えぐい","reading":"えぐい","meaning":"khủng khiếp, quá đà","hanviet":"","example":"①今日の課題の量えぐい。\n②あの選手のシュート、えぐい。\n③今月の電気代、えぐいことになってる。","example_reading":"①きょうのかだいのりょうえぐい。\n②あのせんしゅのしゅーと、えぐい。\n③こんげつのでんきだい、えぐいことになってる。","example_meaning":"①Lượng bài tập hôm nay khủng khiếp.\n②Cú sút của cầu thủ đó khủng khiếp.\n③Tiền điện tháng này cao khủng khiếp.","level":"s2","pos":"adj-i"},
{"word":"やばみ","reading":"やばみ","meaning":"cảm giác \"yabai\"","hanviet":"","example":"①テスト前のやばみがすごい。\n②寝坊したときのやばみは半端ない。\n③電池が残り少なくて、やばみを感じる。","example_reading":"①てすとまえのやばみがすごい。\n②ねぼうしたときのやばみははんぱない。\n③でんちがのこりすくなくて、やばみをかんじる。","example_meaning":"①Cảm giác nguy trước kỳ thi ghê lắm.\n②Cảm giác nguy khi ngủ quên thì khỏi nói.\n③Pin sắp hết, tôi thấy nguy ghê.","level":"s2","pos":"n"},
{"word":"ぴえん","reading":"ぴえん","meaning":"huhu (khóc nhẹ)","hanviet":"","example":"①財布落とした、ぴえん。\n②推しのライブに落ちた、ぴえん。\n③雨なのに傘がない、ぴえん。","example_reading":"①さいふおとした、ぴえん。\n②おしのらいぶにおちた、ぴえん。\n③あめなのにかさがない、ぴえん。","example_meaning":"①Rơi mất ví rồi, huhu.\n②Trượt vé concert của idol rồi, huhu.\n③Trời mưa mà không có ô, huhu.","level":"s2","pos":"int"},
{"word":"きまずい","reading":"きまずい","meaning":"ngượng ngùng, khó xử","hanviet":"","example":"①元カレに会って気まずい。\n②エレベーターで上司と二人きりで気まずい。\n③ケンカした友達と会って気まずい空気になった。","example_reading":"①もとかれにあってきまずい。\n②えれべーたーでじょうしとふたりきりできまずい。\n③けんかしたともだちとあってきまずいくうきになった。","example_meaning":"①Gặp lại người yêu cũ thật khó xử.\n②Ở trong thang máy chỉ có hai người với sếp thật khó xử.\n③Gặp lại bạn vừa cãi nhau, không khí trở nên ngượng ngùng.","level":"s2","pos":"adj-i"},
{"word":"だるい","reading":"だるい","meaning":"lười, uể oải","hanviet":"","antonym":"元気（げんき）: khỏe khoắn","antonym_hanviet":"nguyên khí","example":"①今日は学校だるい。\n②風邪気味で体がだるい。\n③夏は暑くて何もする気がなくてだるい。","example_reading":"①きょうはがっこうだるい。\n②かぜぎみでからだがだるい。\n③なつはあつくてなにもするきがなくてだるい。","example_meaning":"①Hôm nay lười đi học ghê.\n②Hơi cảm nên người uể oải.\n③Mùa hè nóng quá, chẳng muốn làm gì, người cứ uể oải.","level":"s2","pos":"adj-i"},
{"word":"むずい","reading":"むずい","meaning":"khó (nói tắt của 難しい)","hanviet":"","antonym":"易しい（やさしい）: dễ","antonym_hanviet":"dị","example":"①この問題むずい。\n②この英語の宿題、むずい。\n③この文法、むずくない？","example_reading":"①このもんだいむずい。\n②このえいごのしゅくだい、むずい。\n③このぶんぽう、むずくない？","example_meaning":"①Bài này khó quá.\n②Bài tập tiếng Anh này khó quá.\n③Ngữ pháp này khó đúng không?","level":"s2","pos":"adj-i"},
{"word":"うざい","reading":"うざい","meaning":"phiền, khó chịu","hanviet":"","example":"①広告がうざい。\n②弟がうざい。\n③何回も同じ通知が来てうざい。","example_reading":"①こうこくがうざい。\n②おとうとがうざい。\n③なんかいもおなじつうちがきてうざい。","example_meaning":"①Quảng cáo phiền thật.\n②Thằng em tôi phiền chết đi được.\n③Cứ có cùng một thông báo hoài, phiền ghê.","level":"s2","pos":"adj-i"},
{"word":"きも","reading":"きも","meaning":"ghê, gớm (nói tắt 気持ち悪い)","hanviet":"","antonym":"気持ちいい（きもちいい）: dễ chịu","antonym_hanviet":"khí trì","example":"①その虫きも。\n②その色の組み合わせ、ちょっときも。\n③知らない人からのメッセージ、きも。","example_reading":"①そのむしきも。\n②そのいろのくみあわせ、ちょっときも。\n③しらないひとからのめっせーじ、きも。","example_meaning":"①Con sâu đó ghê quá.\n②Cách phối màu đó hơi ghê.\n③Tin nhắn từ người lạ, ghê quá.","level":"s2","pos":"adj-i"},
{"word":"ウケる","reading":"ウケる","meaning":"được lòng, gây cười","hanviet":"","example":"①このネタ、若い子にウケる。\n②この商品、女性にウケるデザインだ。\n③彼のスピーチ、思ったよりウケた。","example_reading":"①このねた、わかいこにうける。\n②このしょうひん、じょせいにうけるでざいんだ。\n③かれのすぴーち、おもったよりうけた。","example_meaning":"①Chiêu này bọn trẻ thích lắm.\n②Sản phẩm này có thiết kế được phụ nữ yêu thích.\n③Bài phát biểu của anh ấy được hưởng ứng hơn tôi nghĩ.","level":"s2","pos":"v"},
{"word":"盛る","reading":"もる","meaning":"làm quá lên, chỉnh ảnh","hanviet":"thịnh","example":"①写真を盛りすぎた。\n②友達は話を盛るのが好きだ。\n③髪を盛って出かけた。","example_reading":"①しゃしんをもりすぎた。\n②ともだちははなしをもるのがすきだ。\n③かみをもってでかけた。","example_meaning":"①Tôi chỉnh ảnh quá đà rồi.\n②Bạn tôi thích nói quá lên.\n③Tôi làm tóc bồng bềnh rồi ra ngoài.","level":"s2","pos":"v"},
{"word":"盛れる","reading":"もれる","meaning":"lên ảnh đẹp","hanviet":"thịnh","example":"①このアプリ、めっちゃ盛れる。\n②このカメラで撮ると、顔が盛れる。\n③今日のメイク、いつもより盛れた。","example_reading":"①このあぷり、めっちゃもれる。\n②このかめらでとると、かおがもれる。\n③きょうのめいく、いつもよりもれた。","example_meaning":"①App này lên ảnh đẹp lắm.\n②Chụp bằng camera này thì mặt lên ảnh đẹp.\n③Trang điểm hôm nay lên ảnh đẹp hơn mọi khi.","level":"s2","pos":"v"},
{"word":"ドタキャン","reading":"ドタキャン","meaning":"hủy hẹn phút chót","hanviet":"","example":"①友達にドタキャンされた。\n②当日にドタキャンはやめてほしい。\n③彼は熱が出て、ドタキャンした。","example_reading":"①ともだちにどたきゃんされた。\n②とうじつにどたきゃんはやめてほしい。\n③かれはねつがでて、どたきゃんした。","example_meaning":"①Bạn tôi hủy hẹn phút chót.\n②Mong đừng hủy hẹn sát giờ ngay trong ngày.\n③Cậu ấy bị sốt nên hủy hẹn phút chót.","level":"s2","pos":"n"},
{"word":"バイト","reading":"バイト","meaning":"làm thêm","hanviet":"","example":"①今日はバイトがある。\n②週に三回、コンビニでバイトしてる。\n③バイトの面接に行ってきた。","example_reading":"①きょうはばいとがある。\n②しゅうにさんかい、こんびにでばいとしてる。\n③ばいとのめんせつにいってきた。","example_meaning":"①Hôm nay tôi có ca làm thêm.\n②Mỗi tuần ba buổi tôi làm thêm ở cửa hàng tiện lợi.\n③Tôi vừa đi phỏng vấn việc làm thêm về.","level":"s2","pos":"n"},
{"word":"チャリ","reading":"チャリ","meaning":"xe đạp (nói tắt)","hanviet":"","example":"①チャリで駅まで行く。\n②チャリのカギをなくした。\n③駅前にチャリを止めた。","example_reading":"①ちゃりでえきまでいく。\n②ちゃりのかぎをなくした。\n③えきまえにちゃりをとめた。","example_meaning":"①Tôi đạp xe ra ga.\n②Tôi làm mất chìa khóa xe đạp.\n③Tôi đỗ xe đạp trước ga.","level":"s2","pos":"n"},
{"word":"コスパ","reading":"コスパ","meaning":"đáng đồng tiền","hanviet":"","example":"①この店はコスパがいい。\n②このスマホ、コスパ最強だよ。\n③コスパを考えて、安い方を選んだ。","example_reading":"①このみせはこすぱがいい。\n②このすまほ、こすぱさいきょうだよ。\n③こすぱをかんがえて、やすいほうをえらんだ。","example_meaning":"①Quán này đáng đồng tiền.\n②Chiếc điện thoại này đáng đồng tiền nhất luôn.\n③Cân nhắc giá trị đồng tiền nên tôi chọn cái rẻ hơn.","level":"s2","pos":"n"},
{"word":"タイパ","reading":"タイパ","meaning":"đáng thời gian bỏ ra","hanviet":"","example":"①動画は倍速でタイパ重視。\n②要約サイトで読むとタイパがいい。\n③タイパが悪いから、その店は行かない。","example_reading":"①どうがはばいそくでたいぱじゅうし。\n②ようやくさいとでよむとたいぱがいい。\n③たいぱがわるいから、そのみせはいかない。","example_meaning":"①Tôi xem video tua nhanh cho tiết kiệm thời gian.\n②Đọc qua trang tóm tắt thì tiết kiệm thời gian.\n③Tốn thời gian quá nên tôi không đến quán đó.","level":"s2","pos":"n"},
{"word":"メンタル","reading":"メンタル","meaning":"tinh thần, tâm lý","hanviet":"","example":"①今日はメンタルが弱ってる。\n②彼はメンタルが強い。\n③メンタルを整えるために散歩する。","example_reading":"①きょうはめんたるがよわってる。\n②かれはめんたるがつよい。\n③めんたるをととのえるためにさんぽする。","example_meaning":"①Hôm nay tinh thần tôi yếu.\n②Cậu ấy có tinh thần thép.\n③Tôi đi dạo để ổn định tinh thần.","level":"s2","pos":"n"},
{"word":"テンション","reading":"テンション","meaning":"hứng khởi, tâm trạng","hanviet":"","example":"①朝からテンション高い。\n②旅行の前日はテンションが上がる。\n③今日はなんだかテンションが低い。","example_reading":"①あさからてんしょんたかい。\n②りょこうのぜんじつはてんしょんがあがる。\n③きょうはなんだかてんしょんがひくい。","example_meaning":"①Từ sáng đã hưng phấn.\n②Ngày trước chuyến du lịch tôi thấy hứng khởi hẳn.\n③Hôm nay không hiểu sao tôi thiếu hứng.","level":"s2","pos":"n"},
{"word":"テンション下がる","reading":"テンションさがる","meaning":"tụt mood","hanviet":"hạ","antonym":"テンション上がる（テンションあがる）: lên mood","antonym_hanviet":"thượng","example":"①雨でテンション下がった。\n②電車が止まってテンション下がる。\n③休みなのに仕事の連絡が来てテンション下がった。","example_reading":"①あめでてんしょんさがった。\n②でんしゃがとまっててんしょんさがる。\n③やすみなのにしごとのれんらくがきててんしょんさがった。","example_meaning":"①Mưa làm tôi tụt mood.\n②Tàu dừng chạy làm tôi tụt mood.\n③Ngày nghỉ mà có tin nhắn công việc làm tôi tụt mood.","level":"s2","pos":"exp"},
{"word":"ノリ","reading":"ノリ","meaning":"bắt nhịp, hợp vibe","hanviet":"","example":"①ノリがいい人が好き。\n②今日の飲み会、みんなノリがよかった。\n③あの人とはノリが合わない。","example_reading":"①のりがいいひとがすき。\n②きょうののみかい、みんなのりがよかった。\n③あのひととはのりがあわない。","example_meaning":"①Tôi thích người biết bắt nhịp.\n②Buổi nhậu hôm nay ai cũng hòa nhịp vui vẻ.\n③Tôi không hợp nhịp với người đó.","level":"s2","pos":"n"},
{"word":"ノリで","reading":"ノリで","meaning":"theo hứng","hanviet":"","example":"①ノリで髪を切った。\n②ノリで告白しちゃった。\n③ノリで買ったけど、使ってない。","example_reading":"①のりでかみをきった。\n②のりでこくはくしちゃった。\n③のりでかったけど、つかってない。","example_meaning":"①Tôi cắt tóc theo hứng.\n②Tôi lỡ tỏ tình theo hứng mất rồi.\n③Mua theo hứng nhưng tôi chưa dùng.","level":"s2","pos":"adv"},
{"word":"お疲れ","reading":"おつかれ","meaning":"chào/cảm ơn khi kết thúc việc","hanviet":"bì","example":"①今日もお疲れ！\n②お疲れ、先に帰るね。\n③「お疲れ〜」「お疲れさま！」","example_reading":"①きょうもおつかれ！\n②おつかれ、さきにかえるね。\n③「おつかれ〜」「おつかれさま！」","example_meaning":"①Hôm nay vất vả rồi nhé!\n②Vất vả rồi, tôi về trước nhé.\n③\"Vất vả rồi~\" — \"Vất vả rồi nhé!\"","level":"s2","pos":"n"},
{"word":"イケてる","reading":"イケてる","meaning":"ngầu, chất","hanviet":"","antonym":"ダサい: quê mùa, kém sành điệu","example":"①その服イケてる。\n②彼の新しい髪型、イケてる。\n③このデザイン、けっこうイケてるね。","example_reading":"①そのふくいけてる。\n②かれのあたらしいかみがた、いけてる。\n③このでざいん、けっこういけてるね。","example_meaning":"①Bộ đồ đó chất đấy.\n②Kiểu tóc mới của cậu ấy ngầu ghê.\n③Thiết kế này khá chất đấy.","level":"s2","pos":"v"},
{"word":"マジか","reading":"マジか","meaning":"thật á?","hanviet":"","example":"①マジか、信じられない。\n②「明日休みだって」「マジか！」\n③マジか、また電車が遅れてる。","example_reading":"①まじか、しんじられない。\n②「あしたやすみだって」「まじか！」\n③まじか、またでんしゃがおくれてる。","example_meaning":"①Thật á, không tin nổi.\n②\"Nghe nói mai được nghỉ\" — \"Thật á!\"\n③Thật á, tàu lại trễ nữa rồi.","level":"s3","pos":"exp"},
{"word":"うそでしょ","reading":"うそでしょ","meaning":"xạo mày (không thể tin)","hanviet":"","example":"①うそでしょ、もう着いたの？\n②うそでしょ、宝くじが当たった？\n③「彼、結婚したらしいよ」「うそでしょ！」","example_reading":"①うそでしょ、もうついたの？\n②うそでしょ、たからくじがあたった？\n③「かれ、けっこんしたらしいよ」「うそでしょ！」","example_meaning":"①Xạo hả, tới rồi á?\n②Xạo hả, trúng xổ số rồi á?\n③\"Nghe nói anh ấy cưới rồi\" — \"Xạo hả!\"","level":"s3","pos":"exp"},
{"word":"まさか","reading":"まさか","meaning":"chẳng lẽ, không lẽ nào","hanviet":"","example":"①まさか本当だとは。\n②まさか、こんなところで会うなんて。\n③まさか、忘れたわけじゃないよね？","example_reading":"①まさかほんとうだとは。\n②まさか、こんなところであうなんて。\n③まさか、わすれたわけじゃないよね？","example_meaning":"①Không ngờ lại là thật.\n②Không ngờ lại gặp nhau ở chỗ này.\n③Chẳng lẽ cậu quên rồi à?","level":"s3","pos":"adv"},
{"word":"ありえない","reading":"ありえない","meaning":"không thể nào","hanviet":"","antonym":"ありえる: có thể xảy ra","example":"①この値段、ありえない。\n②三時間も待たされるなんて、ありえない。\n③あの人が遅刻なんてありえない。","example_reading":"①このねだん、ありえない。\n②さんじかんもまたされるなんて、ありえない。\n③あのひとがちこくなんてありえない。","example_meaning":"①Cái giá này không thể nào.\n②Bị bắt chờ tận ba tiếng, không thể tin nổi.\n③Người đó mà đi trễ thì không thể nào.","level":"s3","pos":"adj-i"},
{"word":"むり","reading":"むり","meaning":"chịu, không nổi","hanviet":"","antonym":"余裕（よゆう）: dư sức, thoải mái","antonym_hanviet":"dư dụ","example":"①もう無理、疲れた。\n②辛い食べ物は無理。\n③今日中に終わらせるのは無理だよ。","example_reading":"①もうむり、つかれた。\n②からいたべものはむり。\n③きょうじゅうにおわらせるのはむりだよ。","example_meaning":"①Chịu rồi, mệt quá.\n②Đồ cay thì tôi chịu không nổi.\n③Xong trong hôm nay thì không thể đâu.","level":"s3","pos":"adj-na"},
{"word":"最高","reading":"さいこう","meaning":"tuyệt nhất","hanviet":"tối cao","antonym":"最悪（さいあく）: tệ nhất / 最低（さいてい）: thấp nhất / 最低賃金（さいていちんぎん）: lương tối thiểu","antonym_hanviet":"tối ác / tối đê / tối đê nhẫm kim","example":"①今日のライブ最高だった。\n②温泉に入って、最高の気分だ。\n③この景色、最高だね。","example_reading":"①きょうのらいぶさいこうだった。\n②おんせんにはいって、さいこうのきぶんだ。\n③このけしき、さいこうだね。","example_meaning":"①Buổi diễn hôm nay tuyệt nhất.\n②Ngâm onsen xong, cảm giác tuyệt vời nhất.\n③Phong cảnh này tuyệt nhất nhỉ.","level":"s3","pos":"n"},
{"word":"最悪","reading":"さいあく","meaning":"tệ nhất","hanviet":"tối ác","antonym":"最高（さいこう）: tuyệt nhất","antonym_hanviet":"tối cao","example":"①財布なくした、最悪。\n②傘を忘れた日に限って雨、最悪。\n③寝坊して電車も逃した、最悪の朝だ。","example_reading":"①さいふなくした、さいあく。\n②かさをわすれたひにかぎってあめ、さいあく。\n③ねぼうしてでんしゃものがした、さいあくのあさだ。","example_meaning":"①Mất ví rồi, tệ nhất.\n②Đúng hôm quên ô là trời mưa, tệ hết sức.\n③Ngủ quên lại lỡ tàu, đúng là buổi sáng tồi tệ nhất.","level":"s3","pos":"n"},
{"word":"助かる","reading":"たすかる","meaning":"đỡ quá, cứu mạng","hanviet":"trợ","antonym":"困る（こまる）: gặp rắc rối","antonym_hanviet":"khốn","example":"①それ、めっちゃ助かる。\n②手伝ってくれて助かった。\n③駅まで送ってもらえると助かる。","example_reading":"①それ、めっちゃたすかる。\n②てつだってくれてたすかった。\n③えきまでおくってもらえるとたすかる。","example_meaning":"①Cái đó cứu tôi thật đấy.\n②Cậu giúp tôi, tôi đỡ quá.\n③Nếu được đưa ra ga thì tôi đỡ quá.","level":"s3","pos":"v"},
{"word":"いいね","reading":"いいね","meaning":"hay đó / nút Like","hanviet":"","example":"①その案いいね。\n②写真に「いいね」を押した。\n③「今度、旅行に行こうよ」「いいね！」","example_reading":"①そのあんいいね。\n②しゃしんに「いいね」をおした。\n③「こんど、りょこうにいこうよ」「いいね！」","example_meaning":"①Ý đó hay đó.\n②Tôi đã nhấn \"Thích\" vào bức ảnh.\n③\"Lần tới đi du lịch đi\" — \"Hay đó!\"","level":"s3","pos":"exp"},
{"word":"なるほど","reading":"なるほど","meaning":"à ra vậy","hanviet":"","example":"①なるほど、そういうことか。\n②なるほど、そういう考え方もあるんだね。\n③説明を聞いて、なるほどと思った。","example_reading":"①なるほど、そういうことか。\n②なるほど、そういうかんがえかたもあるんだね。\n③せつめいをきいて、なるほどとおもった。","example_meaning":"①À ra thế, hóa ra là vậy.\n②À ra vậy, cũng có cách nghĩ như thế nhỉ.\n③Nghe giải thích xong tôi thấy \"à ra thế\".","level":"s3","pos":"int"},
{"word":"たしかに","reading":"たしかに","meaning":"đúng thật","hanviet":"","example":"①たしかにその通りだ。\n②たしかに、言われてみればそうかも。\n③「このカフェ、静かだよね」「たしかに」","example_reading":"①たしかにそのとおりだ。\n②たしかに、いわれてみればそうかも。\n③「このかふぇ、しずかだよね」「たしかに」","example_meaning":"①Đúng là như vậy thật.\n②Đúng thật, nghe nói vậy thì có lẽ đúng.\n③\"Quán này yên tĩnh nhỉ\" — \"Đúng thật.\"","level":"s3","pos":"adv"},
{"word":"ほんとそれ","reading":"ほんとそれ","meaning":"đúng y chang","hanviet":"","example":"①ほんとそれ、同感。\n②「最近忙しすぎるよね」「ほんとそれ」\n③ほんとそれ、私もそう思ってた。","example_reading":"①ほんとそれ、どうかん。\n②「さいきんいそがしすぎるよね」「ほんとそれ」\n③ほんとそれ、わたしもそうおもってた。","example_meaning":"①Đúng y chang, tôi cũng nghĩ vậy.\n②\"Dạo này bận quá nhỉ\" — \"Đúng y chang.\"\n③Đúng y vậy, tôi cũng đang nghĩ thế.","level":"s3","pos":"exp"},
{"word":"わかる","reading":"わかる","meaning":"hiểu mà, đồng cảm","hanviet":"","example":"①わかる、その気持ち。\n②わかる〜、朝は起きられないよね。\n③「推しが尊くて無理」「わかる！」","example_reading":"①わかる、そのきもち。\n②わかる〜、あさはおきられないよね。\n③「おしがとうとくてむり」「わかる！」","example_meaning":"①Hiểu mà, cảm giác đó.\n②Hiểu mà~, buổi sáng khó dậy nhỉ.\n③\"Idol đáng yêu quá chịu không nổi\" — \"Hiểu mà!\"","level":"s3","pos":"v"},
{"word":"やば","reading":"やば","meaning":"ối / đỉnh (rút gọn)","hanviet":"","example":"①やば、遅刻する。\n②やば、鍵閉めたっけ？\n③このバンドの新曲、やば！","example_reading":"①やば、ちこくする。\n②やば、かぎしめたっけ？\n③このばんどのしんきょく、やば！","example_meaning":"①Ối, trễ mất.\n②Ối, tôi có khóa cửa chưa nhỉ?\n③Bài mới của ban nhạc này đỉnh quá!","level":"s3","pos":"adj-i"},
{"word":"うける〜","reading":"うける","meaning":"buồn cười thật","hanviet":"","example":"①え、うける〜。\n②うける〜、その顔。\n③「見て、この猫」「うける〜」","example_reading":"①え、うける〜。\n②うける〜、そのかお。\n③「みて、このねこ」「うける〜」","example_meaning":"①Ơ, buồn cười thật.\n②Buồn cười thật, cái mặt đó.\n③\"Nhìn con mèo này đi\" — \"Buồn cười ghê~\"","level":"s3","pos":"v"},
{"word":"泣ける","reading":"なける","meaning":"cảm động phát khóc","hanviet":"khấp","example":"①この話、泣ける。\n②この映画、ラストが泣ける。\n③母からの手紙に泣けた。","example_reading":"①このはなし、なける。\n②このえいが、らすとがなける。\n③ははからのてがみになけた。","example_meaning":"①Câu chuyện này cảm động phát khóc.\n②Phim này cái kết cảm động phát khóc.\n③Đọc thư của mẹ tôi khóc luôn.","level":"s3","pos":"v"},
{"word":"しみる","reading":"しみる","meaning":"thấm thía","hanviet":"","example":"①その言葉がしみる。\n②疲れた体に温かいスープがしみる。\n③先生の言葉が今になってしみる。","example_reading":"①そのことばがしみる。\n②つかれたからだにあたたかいすーぷがしみる。\n③せんせいのことばがいまになってしみる。","example_meaning":"①Câu nói đó thấm thật.\n②Món súp nóng thấm vào cơ thể mệt mỏi.\n③Giờ tôi mới thấm lời thầy cô nói.","level":"s3","pos":"v"},
{"word":"バイブス","reading":"バイブス","meaning":"vibe, không khí","hanviet":"","example":"①このカフェ、バイブスいい。\n②彼とはバイブスが合う。\n③夜の街のバイブスが好き。","example_reading":"①このかふぇ、ばいぶすいい。\n②かれとはばいぶすがあう。\n③よるのまちのばいぶすがすき。","example_meaning":"①Quán này vibe tốt ghê.\n②Tôi hợp vibe với cậu ấy.\n③Tôi thích cái không khí của phố đêm.","level":"s3","pos":"n"},
{"word":"テンパる","reading":"テンパる","meaning":"cuống, rối","hanviet":"","antonym":"落ち着く（おちつく）: bình tĩnh","antonym_hanviet":"lạc trước","example":"①急に聞かれてテンパった。\n②発表の前にテンパってしまった。\n③忙しすぎてテンパってる。","example_reading":"①きゅうにきかれててんぱった。\n②はっぴょうのまえにてんぱってしまった。\n③いそがしすぎててんぱってる。","example_meaning":"①Bị hỏi bất ngờ nên tôi cuống.\n②Trước khi thuyết trình tôi bị cuống lên.\n③Bận quá nên tôi đang rối tung.","level":"s3","pos":"v"},
{"word":"凹む","reading":"へこむ","meaning":"xuống tinh thần","hanviet":"ao","antonym":"アガる: phấn khích","example":"①失敗して凹んでる。\n②上司に怒られて凹んだ。\n③テストの点が悪くて凹む。","example_reading":"①しっぱいしてへこんでる。\n②じょうしにおこられてへこんだ。\n③てすとのてんがわるくてへこむ。","example_meaning":"①Thất bại nên tôi đang xuống tinh thần.\n②Bị sếp mắng nên tôi xuống tinh thần.\n③Điểm kiểm tra thấp làm tôi chán nản.","level":"s3","pos":"v"},
{"word":"萎える","reading":"なえる","meaning":"hết hứng","hanviet":"nuy","antonym":"アガる: phấn khích","example":"①雨で萎えた。\n②行列が長すぎて萎える。\n③彼の態度に一気に萎えた。","example_reading":"①あめでなえた。\n②ぎょうれつがながすぎてなえる。\n③かれのたいどにいっきになえた。","example_meaning":"①Mưa làm tôi hết hứng.\n②Hàng người dài quá làm tôi hết hứng.\n③Thái độ của anh ta khiến tôi mất hứng hẳn.","level":"s3","pos":"v"},
{"word":"アガる","reading":"アガる","meaning":"phấn khích lên","hanviet":"","antonym":"萎える（なえる）: hết hứng / 凹む（へこむ）: xuống tinh thần","antonym_hanviet":"nuy / ao","example":"①この曲でアガる。\n②好きなアーティストの曲を聴くとアガる。\n③今夜のパーティー、めっちゃアガる！","example_reading":"①このきょくであがる。\n②すきなあーてぃすとのきょくをきくとあがる。\n③こんやのぱーてぃー、めっちゃあがる！","example_meaning":"①Bài này làm tôi phấn khích.\n②Nghe nhạc của nghệ sĩ mình thích là thấy phấn khích.\n③Tiệc tối nay làm tôi phấn khích cực!","level":"s3","pos":"v"},
{"word":"ほっこり","reading":"ほっこり","meaning":"ấm lòng","hanviet":"","example":"①子犬の動画でほっこりした。\n②祖母の手料理を食べてほっこりした。\n③猫が寝ている姿にほっこりする。","example_reading":"①こいぬのどうがでほっこりした。\n②そぼのてりょうりをたべてほっこりした。\n③ねこがねているすがたにほっこりする。","example_meaning":"①Video chó con làm tôi ấm lòng.\n②Ăn món bà nấu làm lòng tôi ấm áp.\n③Nhìn dáng mèo ngủ làm lòng thấy ấm áp.","level":"s3","pos":"adv"},
{"word":"それな案件","reading":"それなあんけん","meaning":"chuyện quá đúng","hanviet":"án kiện","example":"①毎回遅刻、それな案件。\n②朝の満員電車は、まさにそれな案件。\n③給料が上がらないのも、それな案件だよね。","example_reading":"①まいかいちこく、それなあんけん。\n②あさのまんいんでんしゃは、まさにそれなあんけん。\n③きゅうりょうがあがらないのも、それなあんけんだよね。","example_meaning":"①Lần nào cũng trễ, đúng quá đi.\n②Tàu đông nghẹt buổi sáng đúng là chuyện ai cũng gật gù.\n③Chuyện lương không tăng cũng là chuyện \"quá đúng\" nhỉ.","level":"s3","pos":"n"},
{"word":"お手上げ","reading":"おてあげ","meaning":"bó tay","hanviet":"thủ thượng","example":"①もうお手上げだ。\n②このパズルは難しすぎてお手上げだ。\n③機械の故障は、私にはお手上げです。","example_reading":"①もうおてあげだ。\n②このぱずるはむずかしすぎておてあげだ。\n③きかいのこしょうは、わたしにはおてあげです。","example_meaning":"①Tôi bó tay rồi.\n②Câu đố này khó quá, tôi bó tay.\n③Máy hỏng thì tôi chịu bó tay.","level":"s3","pos":"n"},
{"word":"フォロー","reading":"フォロー","meaning":"theo dõi (follow)","hanviet":"","antonym":"アンフォロー: bỏ theo dõi","example":"①この人フォローしてる。\n②好きな俳優をフォローした。\n③フォローありがとうございます！","example_reading":"①このひとふぉろーしてる。\n②すきなはいゆうをふぉろーした。\n③ふぉろーありがとうございます！","example_meaning":"①Tôi đang theo dõi người này.\n②Tôi đã theo dõi diễn viên mình thích.\n③Cảm ơn bạn đã theo dõi!","level":"s4","pos":"n"},
{"word":"フォロワー","reading":"フォロワー","meaning":"người theo dõi","hanviet":"","example":"①フォロワーが増えた。\n②フォロワーが一万人を超えた。\n③彼女はフォロワーが多い。","example_reading":"①ふぉろわーがふえた。\n②ふぉろわーがいちまんにんをこえた。\n③かのじょはふぉろわーがおおい。","example_meaning":"①Lượng follower tăng lên.\n②Số người theo dõi đã vượt mười nghìn.\n③Cô ấy có nhiều người theo dõi.","level":"s4","pos":"n"},
{"word":"リプ","reading":"リプ","meaning":"reply, trả lời bình luận","hanviet":"","example":"①リプありがとう。\n②さっきのツイートにリプが来た。\n③リプで質問してもいいですか？","example_reading":"①りぷありがとう。\n②さっきのついーとにりぷがきた。\n③りぷでしつもんしてもいいですか？","example_meaning":"①Cảm ơn đã rep nhé.\n②Tweet lúc nãy có người rep rồi.\n③Tôi hỏi qua phần trả lời có được không?","level":"s4","pos":"n"},
{"word":"DM","reading":"ディーエム","meaning":"tin nhắn riêng","hanviet":"","example":"①詳しくはDMして。\n②気になったので、DMを送ってみた。\n③DMで連絡してもらえますか？","example_reading":"①くわしくはでぃーえむして。\n②きになったので、でぃーえむをおくってみた。\n③でぃーえむでれんらくしてもらえますか？","example_meaning":"①Chi tiết thì nhắn riêng nhé.\n②Tôi tò mò nên thử nhắn riêng.\n③Bạn liên lạc với tôi qua tin nhắn riêng được không?","level":"s4","pos":"n"},
{"word":"既読","reading":"きどく","meaning":"đã xem (tin nhắn)","hanviet":"ký độc","antonym":"未読（みどく）: chưa đọc","antonym_hanviet":"vị độc","example":"①既読になってる。\n②メッセージに既読がついた。\n③既読になったのに返事がない。","example_reading":"①きどくになってる。\n②めっせーじにきどくがついた。\n③きどくになったのにへんじがない。","example_meaning":"①Đã xem rồi kìa.\n②Tin nhắn đã hiện \"đã xem\".\n③Xem rồi mà không có trả lời.","level":"s4","pos":"n"},
{"word":"既読スルー","reading":"きどくスルー","meaning":"xem rồi mà không rep","hanviet":"ký độc","example":"①既読スルーされた。\n②彼女に既読スルーされて落ち込んだ。\n③既読スルーは良くないよ。","example_reading":"①きどくするーされた。\n②かのじょにきどくするーされておちこんだ。\n③きどくするーはよくないよ。","example_meaning":"①Bị xem rồi bỏ lơ.\n②Bị cô ấy xem rồi bỏ lơ nên tôi buồn.\n③Xem rồi mà không rep thì không hay đâu.","level":"s4","pos":"n"},
{"word":"未読","reading":"みどく","meaning":"chưa đọc","hanviet":"vị độc","antonym":"既読（きどく）: đã xem","antonym_hanviet":"ký độc","example":"①未読が五十件ある。\n②メールが未読のままたまってる。\n③未読の通知を全部消した。","example_reading":"①みどくがごじゅっけんある。\n②めーるがみどくのままたまってる。\n③みどくのつうちをぜんぶけした。","example_meaning":"①Có 50 tin chưa đọc.\n②Email cứ ở trạng thái chưa đọc rồi dồn lại.\n③Tôi đã xóa hết thông báo chưa đọc.","level":"s4","pos":"n"},
{"word":"ブロック","reading":"ブロック","meaning":"chặn","hanviet":"","antonym":"ブロック解除（ブロックかいじょ）: bỏ chặn","antonym_hanviet":"giải trừ","example":"①しつこいのでブロックした。\n②迷惑メールの送信者をブロックした。\n③元カレをブロックして、すっきりした。","example_reading":"①しつこいのでぶろっくした。\n②めいわくめーるのそうしんしゃをぶろっくした。\n③もとかれをぶろっくして、すっきりした。","example_meaning":"①Phiền quá nên tôi chặn luôn.\n②Tôi đã chặn người gửi thư rác.\n③Chặn người yêu cũ xong, tôi thấy nhẹ nhõm.","level":"s4","pos":"n"},
{"word":"ミュート","reading":"ミュート","meaning":"tắt thông báo","hanviet":"","antonym":"ミュート解除（ミュートかいじょ）: bật lại thông báo","antonym_hanviet":"giải trừ","example":"①通知をミュートした。\n②うるさいグループチャットをミュートした。\n③会議中はマイクをミュートにしてね。","example_reading":"①つうちをみゅーとした。\n②うるさいぐるーぷちゃっとをみゅーとした。\n③かいぎちゅうはまいくをみゅーとにしてね。","example_meaning":"①Tôi đã tắt thông báo.\n②Tôi đã tắt thông báo nhóm chat ồn ào.\n③Trong lúc họp nhớ tắt mic nhé.","level":"s4","pos":"n"},
{"word":"バズ","reading":"バズ","meaning":"cú viral","hanviet":"","example":"①一晩でバズが起きた。\n②バズを狙って投稿する。\n③今回のバズで、商品が売り切れた。","example_reading":"①ひとばんでばずがおきた。\n②ばずをねらってとうこうする。\n③こんかいのばずで、しょうひんがうりきれた。","example_meaning":"①Chỉ một đêm là viral.\n②Đăng bài nhắm tới việc viral.\n③Nhờ cú viral lần này mà sản phẩm bán hết sạch.","level":"s4","pos":"n"},
{"word":"炎上","reading":"えんじょう","meaning":"bị ném đá tập thể","hanviet":"viêm thượng","example":"①発言が炎上した。\n②不用意なツイートで炎上した。\n③炎上するのが怖くて、何も書けない。","example_reading":"①はつげんがえんじょうした。\n②ふよういなついーとでえんじょうした。\n③えんじょうするのがこわくて、なにもかけない。","example_meaning":"①Phát ngôn đó bị ném đá.\n②Vì một tweet thiếu cẩn trọng mà bị ném đá.\n③Sợ bị ném đá nên tôi chẳng dám viết gì.","level":"s4","pos":"n"},
{"word":"ステマ","reading":"ステマ","meaning":"quảng cáo trá hình","hanviet":"","example":"①それステマじゃない？\n②この口コミ、ステマっぽい。\n③ステマは規制されるようになった。","example_reading":"①それすてまじゃない？\n②このくちこみ、すてまっぽい。\n③すてまはきせいされるようになった。","example_meaning":"①Cái đó quảng cáo trá hình à?\n②Đánh giá này nhìn giống quảng cáo trá hình.\n③Quảng cáo trá hình giờ đã bị quản lý chặt hơn.","level":"s4","pos":"n"},
{"word":"案件","reading":"あんけん","meaning":"bài PR được trả tiền","hanviet":"án kiện","example":"①この投稿は案件です。\n②初めて企業から案件をもらった。\n③案件の依頼がDMで届いた。","example_reading":"①このとうこうはあんけんです。\n②はじめてきぎょうからあんけんをもらった。\n③あんけんのいらいがでぃーえむでとどいた。","example_meaning":"①Bài đăng này là bài PR.\n②Lần đầu tôi nhận được bài PR từ doanh nghiệp.\n③Lời mời làm bài PR đã gửi đến qua tin nhắn riêng.","level":"s4","pos":"n"},
{"word":"垢","reading":"あか","meaning":"tài khoản (account)","hanviet":"cấu","example":"①裏垢を作った。\n②新しい垢を作ってみた。\n③垢を消そうか迷っている。","example_reading":"①うらあかをつくった。\n②あたらしいあかをつくってみた。\n③あかをけそうかまよっている。","example_meaning":"①Tôi lập tài khoản phụ.\n②Tôi thử lập một tài khoản mới.\n③Tôi đang phân vân có nên xóa tài khoản không.","level":"s4","pos":"n"},
{"word":"裏垢","reading":"うらあか","meaning":"tài khoản phụ/ẩn danh","hanviet":"lý cấu","antonym":"本垢（ほんあか）: tài khoản chính","antonym_hanviet":"bản cấu","example":"①裏垢でつぶやく。\n②裏垢では本音を書いている。\n③友達に裏垢がばれた。","example_reading":"①うらあかでつぶやく。\n②うらあかではほんねをかいている。\n③ともだちにうらあかがばれた。","example_meaning":"①Tôi lảm nhảm trên tài khoản phụ.\n②Ở tài khoản phụ tôi viết ra những điều thật lòng.\n③Tài khoản phụ của tôi bị bạn phát hiện rồi.","level":"s4","pos":"n"},
{"word":"鍵垢","reading":"かぎあか","meaning":"tài khoản ở chế độ riêng tư","hanviet":"kiện cấu","antonym":"公開アカウント（こうかいアカウント）: tài khoản công khai","antonym_hanviet":"công khai","example":"①鍵垢だから見られない。\n②彼の鍵垢にフォロー申請した。\n③最近、鍵垢にする人が増えている。","example_reading":"①かぎあかだからみられない。\n②かれのかぎあかにふぉろーしんせいした。\n③さいきん、かぎあかにするひとがふえている。","example_meaning":"①Tài khoản khóa nên không xem được.\n②Tôi đã gửi yêu cầu theo dõi tài khoản riêng tư của cậu ấy.\n③Dạo này ngày càng nhiều người để tài khoản ở chế độ riêng tư.","level":"s4","pos":"n"},
{"word":"ストーリー","reading":"ストーリー","meaning":"story (tin 24h)","hanviet":"","example":"①ストーリーに上げた。\n②旅行の写真をストーリーにあげた。\n③ストーリーは24時間で消える。","example_reading":"①すとーりーにあげた。\n②りょこうのしゃしんをすとーりーにあげた。\n③すとーりーはにじゅうよじかんできえる。","example_meaning":"①Tôi đăng lên story rồi.\n②Tôi đăng ảnh chuyến du lịch lên story.\n③Story sẽ biến mất sau 24 giờ.","level":"s4","pos":"n"},
{"word":"投稿","reading":"とうこう","meaning":"bài đăng","hanviet":"đầu cảo","example":"①新しい投稿を見た。\n②毎日、写真を投稿している。\n③彼の投稿にコメントした。","example_reading":"①あたらしいとうこうをみた。\n②まいにち、しゃしんをとうこうしている。\n③かれのとうこうにこめんとした。","example_meaning":"①Tôi thấy bài đăng mới.\n②Ngày nào tôi cũng đăng ảnh.\n③Tôi đã bình luận vào bài đăng của cậu ấy.","level":"s4","pos":"n"},
{"word":"拡散","reading":"かくさん","meaning":"chia sẻ lan truyền","hanviet":"khoách tán","antonym":"集中（しゅうちゅう）: tập trung","antonym_hanviet":"tập trung","example":"①拡散お願いします。\n②迷い猫の情報を拡散した。\n③このニュースは一気に拡散された。","example_reading":"①かくさんおねがいします。\n②まよいねこのじょうほうをかくさんした。\n③このにゅーすはいっきにかくさんされた。","example_meaning":"①Mong mọi người chia sẻ giúp.\n②Tôi đã chia sẻ thông tin về con mèo lạc.\n③Tin này lan truyền chóng mặt.","level":"s4","pos":"n"},
{"word":"晒す","reading":"さらす","meaning":"bêu lên mạng","hanviet":"sái","example":"①名前を晒すのはよくない。\n②友達の写真を勝手に晒さないで。\n③個人情報を晒されて困っている。","example_reading":"①なまえをさらすのはよくない。\n②ともだちのしゃしんをかってにさらさないで。\n③こじんじょうほうをさらされてこまっている。","example_meaning":"①Bêu tên người khác là không tốt.\n②Đừng tự ý đăng ảnh bạn bè lên để bêu.\n③Tôi đang gặp rắc rối vì bị tung thông tin cá nhân lên mạng.","level":"s4","pos":"v"},
{"word":"匿名","reading":"とくめい","meaning":"ẩn danh","hanviet":"nặc danh","antonym":"実名（じつめい）: tên thật","antonym_hanviet":"thực danh","example":"①匿名で書き込む。\n②匿名のアカウントから批判された。\n③アンケートは匿名で答えられます。","example_reading":"①とくめいでかきこむ。\n②とくめいのあかうんとからひはんされた。\n③あんけーとはとくめいでこたえられます。","example_meaning":"①Đăng bài ẩn danh.\n②Tôi bị chỉ trích từ một tài khoản ẩn danh.\n③Khảo sát có thể trả lời ẩn danh.","level":"s4","pos":"n"},
{"word":"荒らし","reading":"あらし","meaning":"kẻ phá rối trên mạng","hanviet":"hoang","example":"①荒らしは無視しよう。\n②掲示板に荒らしが現れた。\n③荒らしコメントは報告するといいよ。","example_reading":"①あらしはむししよう。\n②けいじばんにあらしがあらわれた。\n③あらしこめんとはほうこくするといいよ。","example_meaning":"①Kệ mấy người phá rối đi.\n②Trên diễn đàn xuất hiện kẻ phá rối.\n③Gặp bình luận phá rối thì nên báo cáo.","level":"s4","pos":"n"},
{"word":"まとめ","reading":"まとめ","meaning":"bài tổng hợp","hanviet":"","example":"①まとめ記事を読んだ。\n②ネットのまとめサイトでニュースを知った。\n③試合のまとめを動画で見た。","example_reading":"①まとめきじをよんだ。\n②ねっとのまとめさいとでにゅーすをしった。\n③しあいのまとめをどうがでみた。","example_meaning":"①Tôi đọc bài tổng hợp.\n②Tôi biết tin qua trang tổng hợp trên mạng.\n③Tôi xem video tóm tắt trận đấu.","level":"s4","pos":"n"},
{"word":"ネタバレ","reading":"ネタバレ","meaning":"spoil nội dung","hanviet":"","example":"①ネタバレやめて。\n②映画のネタバレを見ちゃった。\n③ネタバレ禁止でお願いします。","example_reading":"①ねたばれやめて。\n②えいがのねたばれをみちゃった。\n③ねたばれきんしでおねがいします。","example_meaning":"①Đừng spoil nữa.\n②Tôi lỡ đọc phải spoil của bộ phim.\n③Xin đừng spoil nhé.","level":"s4","pos":"n"},
{"word":"ROM専","reading":"ロムせん","meaning":"chỉ đọc không đăng","hanviet":"chuyên","example":"①私はROM専です。\n②掲示板では、ずっとROM専だった。\n③ROM専をやめて、初めて書き込んだ。","example_reading":"①わたしはろむせんです。\n②けいじばんでは、ずっとろむせんだった。\n③ろむせんをやめて、はじめてかきこんだ。","example_meaning":"①Tôi chỉ đọc chứ không đăng.\n②Trên diễn đàn tôi luôn chỉ đọc chứ không đăng.\n③Tôi bỏ thói chỉ đọc mà lần đầu viết bài.","level":"s4","pos":"n"},
{"word":"オフ会","reading":"オフかい","meaning":"gặp mặt ngoài đời","hanviet":"hội","example":"①来月オフ会がある。\n②ネット友達とオフ会で初めて会った。\n③週末のオフ会に参加する予定だ。","example_reading":"①らいげつおふかいがある。\n②ねっとともだちとおふかいではじめてあった。\n③しゅうまつのおふかいにさんかするよていだ。","example_meaning":"①Tháng sau có buổi gặp mặt offline.\n②Lần đầu tôi gặp bạn mạng trong buổi offline.\n③Tôi định tham gia buổi gặp mặt offline cuối tuần.","level":"s4","pos":"n"},
{"word":"ってか","reading":"ってか","meaning":"mà này, nói đúng hơn là","hanviet":"","example":"①ってか、もう帰らない？\n②ってか、お腹すいてない？\n③ってか、その話さっきも聞いたよ。","example_reading":"①ってか、もうかえらない？\n②ってか、おなかすいてない？\n③ってか、そのはなしさっきもきいたよ。","example_meaning":"①Mà này, về luôn không?\n②Mà này, cậu không đói à?\n③Mà này, chuyện đó lúc nãy tôi nghe rồi.","level":"s5","pos":"conj"},
{"word":"てゆうか","reading":"てゆうか","meaning":"nói cách khác, mà","hanviet":"","example":"①てゆうか、それ本当？\n②てゆうか、先に言ってよ。\n③てゆうか、今日って何曜日だっけ？","example_reading":"①てゆうか、それほんとう？\n②てゆうか、さきにいってよ。\n③てゆうか、きょうってなんようびだっけ？","example_meaning":"①Mà này, cái đó thật à?\n②Mà này, nói trước đi chứ.\n③Mà này, hôm nay là thứ mấy nhỉ?","level":"s5","pos":"conj"},
{"word":"じゃん","reading":"じゃん","meaning":"đúng không (thân mật)","hanviet":"","example":"①いい感じじゃん。\n②それ、すごいじゃん！\n③前にも言ったじゃん。","example_reading":"①いいかんじじゃん。\n②それ、すごいじゃん！\n③まえにもいったじゃん。","example_meaning":"①Ổn đấy chứ.\n②Cái đó giỏi đấy chứ!\n③Trước đó tôi cũng nói rồi mà.","level":"s5","pos":"exp"},
{"word":"だろ","reading":"だろ","meaning":"đúng không (nam giới)","hanviet":"","example":"①言っただろ。\n②お前、知ってただろ？\n③大丈夫だろ、そのうち来るよ。","example_reading":"①いっただろ。\n②おまえ、しってただろ？\n③だいじょうぶだろ、そのうちくるよ。","example_meaning":"①Đã bảo rồi mà.\n②Cậu biết từ trước rồi đúng không?\n③Chắc không sao đâu, rồi cũng đến thôi.","level":"s5","pos":"exp"},
{"word":"っす","reading":"っす","meaning":"です rút gọn (thân mật)","hanviet":"","example":"①大丈夫っす。\n②今日は暇っす。\n③了解っす！","example_reading":"①だいじょうぶっす。\n②きょうはひまっす。\n③りょうかいっす！","example_meaning":"①Không sao đâu ạ.\n②Hôm nay em rảnh ạ.\n③Em hiểu rồi ạ!","level":"s5","pos":"exp"},
{"word":"なんか","reading":"なんか","meaning":"kiểu như, gì đó","hanviet":"","example":"①なんか疲れた。\n②なんか、今日は調子いいな。\n③なんか食べに行かない？","example_reading":"①なんかつかれた。\n②なんか、きょうはちょうしいいな。\n③なんかたべにいかない？","example_meaning":"①Kiểu như là mệt ấy.\n②Kiểu như hôm nay trạng thái tốt ghê.\n③Đi ăn gì đó không?","level":"s5","pos":"adv"},
{"word":"とりま","reading":"とりま","meaning":"tạm thời thì (とりあえず まあ)","hanviet":"","example":"①とりま集合しよう。\n②とりま、お茶でも飲もう。\n③とりま、連絡だけしておくね。","example_reading":"①とりましゅうごうしよう。\n②とりま、おちゃでものもう。\n③とりま、れんらくだけしておくね。","example_meaning":"①Tạm thời thì tụ lại cái đã.\n②Tạm thời uống chút trà đã.\n③Trước mắt tôi cứ báo trước một tiếng nhé.","level":"s5","pos":"adv"},
{"word":"ちな","reading":"ちな","meaning":"nhân tiện (ちなみに)","hanviet":"","example":"①ちな、明日休みだよ。\n②ちな、私は来週から出張だよ。\n③ちな、あの店は月曜休みだよ。","example_reading":"①ちな、あしたやすみだよ。\n②ちな、わたしはらいしゅうからしゅっちょうだよ。\n③ちな、あのみせはげつようやすみだよ。","example_meaning":"①Nhân tiện, mai nghỉ đấy.\n②Nhân tiện, tuần sau tôi đi công tác đấy.\n③Nhân tiện, quán đó nghỉ thứ Hai đấy.","level":"s5","pos":"conj"},
{"word":"あざす","reading":"あざす","meaning":"cảm ơn (rút gọn)","hanviet":"","example":"①マジあざす！\n②先輩、ごちそうさまです、あざす！\n③教えてくれて、あざす。","example_reading":"①まじあざす！\n②せんぱい、ごちそうさまです、あざす！\n③おしえてくれて、あざす。","example_meaning":"①Cảm ơn thật nhiều!\n②Tiền bối, em cảm ơn vì đã đãi ạ!\n③Cảm ơn đã chỉ cho em.","level":"s5","pos":"int"},
{"word":"りょ","reading":"りょ","meaning":"okay, đã hiểu (了解)","hanviet":"","example":"①りょ、後で行く。\n②「六時に集合ね」「りょ」\n③りょ！すぐ行くね。","example_reading":"①りょ、あとでいく。\n②「ろくじにしゅうごうね」「りょ」\n③りょ！すぐいくね。","example_meaning":"①Ok, lát tôi qua.\n②\"Tập trung lúc 6 giờ nhé\" — \"Ok, hiểu.\"\n③Ok! Tôi đến ngay.","level":"s5","pos":"int"},
{"word":"おけ","reading":"おけ","meaning":"ok","hanviet":"","example":"①おけ、了解した。\n②「これでいい？」「おけ！」\n③おけ、じゃあ明日ね。","example_reading":"①おけ、りょうかいした。\n②「これでいい？」「おけ！」\n③おけ、じゃああしたね。","example_meaning":"①Ok, hiểu rồi.\n②\"Thế này được không?\" — \"Ok!\"\n③Ok, vậy mai nhé.","level":"s5","pos":"int"},
{"word":"ムズい","reading":"ムズい","meaning":"khó","hanviet":"","antonym":"易しい（やさしい）: dễ","antonym_hanviet":"dị","example":"①この漢字ムズい。\n②この曲、ギターで弾くのがムズい。\n③日本語の敬語、ムズいよね。","example_reading":"①このかんじむずい。\n②このきょく、ぎたーでひくのがむずい。\n③にほんごのけいご、むずいよね。","example_meaning":"①Chữ Hán này khó thật.\n②Bài này chơi guitar khó thật.\n③Kính ngữ tiếng Nhật khó nhỉ.","level":"s5","pos":"adj-i"},
{"word":"みが深い","reading":"みがふかい","meaning":"cảm giác ... rất sâu","hanviet":"thâm","example":"①眠みが深い。\n②冬の朝は布団から出られなくて寒みが深い。\n③彼の優しさにありがたみが深い。","example_reading":"①ねむみがふかい。\n②ふゆのあさはふとんからでられなくてさむみがふかい。\n③かれのやさしさにありがたみがふかい。","example_meaning":"①Cơn buồn ngủ sâu lắm.\n②Sáng mùa đông không chui khỏi chăn nổi, lạnh thấu xương.\n③Lòng tốt của cậu ấy làm tôi thấy biết ơn sâu sắc.","level":"s5","pos":"exp"},
{"word":"寝落ち","reading":"ねおち","meaning":"ngủ gục giữa chừng","hanviet":"tẩm lạc","antonym":"徹夜（てつや）: thức trắng","antonym_hanviet":"triệt dạ","example":"①動画見ながら寝落ちした。\n②昨日は電気をつけたまま寝落ちした。\n③通話しながら寝落ちしちゃった。","example_reading":"①どうがみながらねおちした。\n②きのうはでんきをつけたままねおちした。\n③つうわしながらねおちしちゃった。","example_meaning":"①Xem video rồi ngủ gục luôn.\n②Hôm qua tôi để đèn sáng mà ngủ gục luôn.\n③Tôi vừa gọi điện vừa ngủ gục mất.","level":"s5","pos":"n"},
{"word":"食レポ","reading":"しょくレポ","meaning":"review đồ ăn","hanviet":"thực","example":"①食レポ動画が好き。\n②彼の食レポは本当においしそうに見える。\n③食レポって意外と難しい。","example_reading":"①しょくれぽどうががすき。\n②かれのしょくれぽはほんとうにおいしそうにみえる。\n③しょくれぽっていがいとむずかしい。","example_meaning":"①Tôi thích video review đồ ăn.\n②Review đồ ăn của anh ấy nhìn ngon thật sự.\n③Review đồ ăn hóa ra khá khó.","level":"s5","pos":"n"},
{"word":"女子会","reading":"じょしかい","meaning":"buổi tụ họp của hội chị em","hanviet":"nữ tử hội","antonym":"男子会（だんしかい）: hội anh em","antonym_hanviet":"nam tử hội","example":"①今夜は女子会。\n②週末に女子会を開く予定だ。\n③女子会で恋バナをした。","example_reading":"①こんやはじょしかい。\n②しゅうまつにじょしかいをひらくよていだ。\n③じょしかいでこいばなをした。","example_meaning":"①Tối nay hội chị em tụ tập.\n②Cuối tuần tôi định tổ chức tiệc hội chị em.\n③Ở buổi họp hội chị em, tụi tôi tám chuyện tình yêu.","level":"s5","pos":"n"},
{"word":"飲み","reading":"のみ","meaning":"đi nhậu (rút gọn)","hanviet":"ẩm","example":"①今日飲み行かない？\n②金曜の夜は飲みに行く予定だ。\n③久しぶりに同期と飲みに行った。","example_reading":"①きょうのみいかない？\n②きんようのよるはのみにいくよていだ。\n③ひさしぶりにどうきとのみにいった。","example_meaning":"①Hôm nay đi nhậu không?\n②Tối thứ Sáu tôi định đi nhậu.\n③Lâu rồi tôi mới đi nhậu cùng đồng nghiệp cùng đợt vào công ty.","level":"s5","pos":"n"},
{"word":"待ち合わせ","reading":"まちあわせ","meaning":"hẹn gặp","hanviet":"đãi hợp","example":"①駅で待ち合わせね。\n②待ち合わせの時間に遅れそう。\n③待ち合わせ場所を変えない？","example_reading":"①えきでまちあわせね。\n②まちあわせのじかんにおくれそう。\n③まちあわせばしょをかえない？","example_meaning":"①Hẹn ở ga nhé.\n②Có vẻ tôi sẽ trễ giờ hẹn.\n③Mình đổi chỗ hẹn nhé?","level":"s5","pos":"n"},
{"word":"行けたら行く","reading":"いけたらいく","meaning":"được thì tới (thường là không tới)","hanviet":"hành","example":"①「来る？」「行けたら行く」\n②「パーティー来る？」「行けたら行くね」\n③彼の「行けたら行く」は、たいてい来ない。","example_reading":"①「くる？」「いけたらいく」\n②「ぱーてぃーくる？」「いけたらいくね」\n③かれの「いけたらいく」は、たいていこない。","example_meaning":"①\"Tới không?\" — \"Được thì tới\"\n②\"Cậu đến tiệc không?\" — \"Được thì tôi tới nhé.\"\n③Câu \"được thì tới\" của cậu ấy thường là không tới.","level":"s5","pos":"exp"},
{"word":"あとで","reading":"あとで","meaning":"lát nữa","hanviet":"","antonym":"すぐに: ngay lập tức","example":"①あとで連絡するね。\n②今は忙しいから、あとで話そう。\n③あとで写真を送るね。","example_reading":"①あとでれんらくするね。\n②いまはいそがしいから、あとではなそう。\n③あとでしゃしんをおくるね。","example_meaning":"①Lát tôi liên lạc nhé.\n②Giờ tôi bận, lát nữa nói chuyện nhé.\n③Lát tôi gửi ảnh cho nhé.","level":"s5","pos":"adv"},
{"word":"ワンチャン","reading":"ワンチャン","meaning":"biết đâu, có cơ hội","hanviet":"","example":"①ワンチャン間に合うかも。\n②ワンチャン、まだ席あるかもよ。\n③ワンチャン狙って、聞いてみよう。","example_reading":"①わんちゃんまにあうかも。\n②わんちゃん、まだせきあるかもよ。\n③わんちゃんねらって、きいてみよう。","example_meaning":"①Biết đâu lại kịp.\n②Biết đâu vẫn còn chỗ ngồi đấy.\n③Thử hỏi xem, biết đâu có cơ hội.","level":"s5","pos":"n"},
{"word":"しかない","reading":"しかない","meaning":"chỉ còn cách","hanviet":"","example":"①もう行くしかない。\n②時間がないから、急ぐしかない。\n③こうなったら、やるしかない。","example_reading":"①もういくしかない。\n②じかんがないから、いそぐしかない。\n③こうなったら、やるしかない。","example_meaning":"①Chỉ còn cách đi thôi.\n②Không còn thời gian nên chỉ còn cách nhanh lên.\n③Đã vậy thì chỉ còn cách làm thôi.","level":"s5","pos":"exp"},
{"word":"ぶっちゃけ","reading":"ぶっちゃけ","meaning":"nói thẳng ra thì","hanviet":"","example":"①ぶっちゃけ興味ない。\n②ぶっちゃけ、あの映画は微妙だった。\n③ぶっちゃけ、もう疲れた。","example_reading":"①ぶっちゃけきょうみない。\n②ぶっちゃけ、あのえいがはびみょうだった。\n③ぶっちゃけ、もうつかれた。","example_meaning":"①Nói thẳng là tôi không hứng thú.\n②Nói thẳng ra, phim đó cũng tàm tạm.\n③Nói thật, tôi mệt rồi.","level":"s5","pos":"adv"},
{"word":"さすが","reading":"さすが","meaning":"quả nhiên là, đúng là","hanviet":"","example":"①さすが、早いね。\n②さすが先生、説明が分かりやすい。\n③一位だって？さすがだね。","example_reading":"①さすが、はやいね。\n②さすがせんせい、せつめいがわかりやすい。\n③いちいだって？さすがだね。","example_meaning":"①Đúng là nhanh thật.\n②Đúng là thầy/cô, giải thích dễ hiểu thật.\n③Hạng nhất à? Quả là giỏi nhỉ.","level":"s5","pos":"adv"},
{"word":"うわ","reading":"うわ","meaning":"ối, oà (thán từ)","hanviet":"","example":"①うわ、びっくりした。\n②うわ、すごい人！\n③うわ、またミスした。","example_reading":"①うわ、びっくりした。\n②うわ、すごいひと！\n③うわ、またみすした。","example_meaning":"①Ối, giật cả mình.\n②Ối, đông người quá!\n③Ối, lại sai nữa rồi.","level":"s5","pos":"int"},
{"word":"やらかす","reading":"やらかす","meaning":"gây chuyện, làm hỏng","hanviet":"","example":"①今日はやらかした。\n②大事なメールを間違えて送ってやらかした。\n③彼はまたやらかしたらしい。","example_reading":"①きょうはやらかした。\n②だいじなめーるをまちがえておくってやらかした。\n③かれはまたやらかしたらしい。","example_meaning":"①Hôm nay tôi làm hỏng việc rồi.\n②Tôi gửi nhầm email quan trọng, làm hỏng bét rồi.\n③Nghe nói cậu ấy lại gây chuyện nữa rồi.","level":"s5","pos":"v"}
],
"grammar": [
{"pattern":"～じゃん","usage":"đúng không, mà (xác nhận thân mật)","example":"それ、前に言ったじゃん。","example_reading":"それ、まえにいったじゃん。","example_meaning":"Cái đó tôi nói rồi mà."},
{"pattern":"～っしょ","usage":"chắc chắn là vậy rồi (でしょ rút gọn)","example":"明日休みっしょ。","example_reading":"あしたやすみっしょ。","example_meaning":"Mai nghỉ mà đúng không."},
{"pattern":"～てる","usage":"đang... (ている rút gọn)","example":"今、何してる？","example_reading":"いま、なにしてる？","example_meaning":"Giờ đang làm gì đấy?"},
{"pattern":"～とく","usage":"làm sẵn (ておく rút gọn)","example":"席取っとくね。","example_reading":"せきとっとくね。","example_meaning":"Tôi giữ chỗ sẵn nhé."},
{"pattern":"～ちゃう","usage":"lỡ mất (てしまう rút gọn)","example":"全部食べちゃった。","example_reading":"ぜんぶたべちゃった。","example_meaning":"Tôi ăn hết sạch mất rồi."},
{"pattern":"～なきゃ","usage":"phải làm (なければ rút gọn)","example":"もう行かなきゃ。","example_reading":"もういかなきゃ。","example_meaning":"Tôi phải đi rồi."},
{"pattern":"～ないと","usage":"không thì gay (省略 kết thúc)","example":"早く寝ないと。","example_reading":"はやくねないと。","example_meaning":"Phải ngủ sớm không thì gay."},
{"pattern":"～かも","usage":"có lẽ (かもしれない rút gọn)","example":"遅れるかも。","example_reading":"おくれるかも。","example_meaning":"Chắc tôi sẽ trễ."},
{"pattern":"～みたいな","usage":"kiểu như là","example":"えっ、マジ？みたいな。","example_reading":"えっ、まじ？みたいな。","example_meaning":"Kiểu như là \"ơ, thật á?\" ấy."},
{"pattern":"～って","usage":"nghe nói là / cái gọi là","example":"彼、来ないって。","example_reading":"かれ、こないって。","example_meaning":"Nghe nói cậu ấy không tới."},
{"pattern":"～し","usage":"vì...với lại","example":"眠いし、もう帰る。","example_reading":"ねむいし、もうかえる。","example_meaning":"Buồn ngủ với lại tôi về đây."},
{"pattern":"～わけ","usage":"hóa ra là (thân mật)","example":"だから遅れたわけ。","example_reading":"だからおくれたわけ。","example_meaning":"Hóa ra vì thế mà trễ."}
]
};
